  "arxiv/editor": "/* The look is style.css; the editor only adds the commas the PDF byline has between names. */\n.paper-pdf.ProseMirror .p-authors > :is(span[data-rash-author], .author-marks):has(+ :is(span[data-rash-author], img.ProseMirror-separator))::after { content: \",\"; margin-right: .35em; }\n.paper-pdf.ProseMirror .p-authors > span[data-rash-author]:focus, .paper-pdf.ProseMirror .p-authors > span[data-rash-author].ProseMirror-selectednode { outline: none; }\n/* No frame around selected or focused text (names, keywords, citations); a selected image keeps its outline. */\n.paper-pdf.ProseMirror :is(span, p, h1, a, button, section, li, td, th):is(:focus, :focus-visible, .ProseMirror-selectednode) { outline: none; box-shadow: none; }\n/* Names run one after the other in a row and wrap as text; a name never splits from its marks. */\n.paper-pdf.ProseMirror .p-authors { display: block; white-space: normal; }\n.paper-pdf.ProseMirror .p-authors > :is(span[data-rash-author], .author-marks) { display: inline; white-space: nowrap; }\n/* ProseMirror's filler image after the affiliations would add an empty line the PDF does not have. */\n.paper-pdf.ProseMirror .p-authors > .byline-extra ~ img.ProseMirror-separator { display: none !important; }\n\n/* Authors in columns, as in the PDF: a name over its own affiliations and email. Names and their notes alternate in the byline, so a two-row grid filled by column pairs each name with its notes. */\n.paper-pdf.ProseMirror .p-authors:has(> [data-rash-author]) { display: grid; grid-auto-flow: column; grid-auto-columns: 16em; grid-template-rows: auto auto; justify-content: center; column-gap: 2em; font-weight: 400; }\n.paper-pdf.ProseMirror .p-authors:has(> [data-rash-author]) > span[data-rash-author] { display: block; text-align: center; font-weight: 700; white-space: normal; }\n.paper-pdf.ProseMirror .p-authors > span[data-rash-author]::after, .paper-pdf.ProseMirror .p-authors > .author-marks::after { content: none !important; }\n.paper-pdf.ProseMirror .p-authors:has(> [data-rash-author]) > .author-marks { overflow-wrap: anywhere; display: flex; flex-direction: column; align-items: center; margin: 0; white-space: normal; min-width: 0; }\n.paper-pdf.ProseMirror .author-marks sup { display: none; }\n.paper-pdf.ProseMirror .author-line { display: block; }\n.paper-pdf.ProseMirror .author-mail { font-family: \"Courier New\", Courier, monospace; font-size: .8em; overflow-wrap: normal; }\n.paper-pdf.ProseMirror .p-authors > .byline-extra { grid-column: 1 / -1; grid-row: 3; text-align: center; }\n.paper-pdf.ProseMirror .byline-extra .affiliation { display: none; }\n.paper-pdf.ProseMirror .byline-extra .byline-date { display: block; margin-top: 20pt; font-weight: 400; }\n/* The author footnote (corresponding author): the editor has no page bottom, so it sits under the byline in small type. */\n.paper-pdf.ProseMirror .byline-extra .affiliation[data-note]:not(.emails) { display: block; margin-top: 8pt; font: 400 .85em/1.2 var(--serif); }\n/* Keywords go below the abstract, as in the PDF: the page is a column, so order moves them. */\n.paper-pdf.ProseMirror { display: flex; flex-direction: column; }\n.paper-pdf.ProseMirror > .p-keywords, .paper-pdf.ProseMirror > .add-abstract { order: 1; }\n.paper-pdf.ProseMirror > :not(.p-title, .p-subtitle, .p-authors, .p-keywords, .add-abstract, section[role=\"doc-abstract\"]) { order: 2; }\n/* ProseMirror's filler image and trailing break would each take a grid cell and shift every name against its notes. */\n.paper-pdf.ProseMirror .p-authors:has(> [data-rash-author]) > :is(img.ProseMirror-separator, br) { display: none !important; }\n/* The ORCID badge goes before the name, as in the template; the name carries data-orcid when there is one. */\n.paper-pdf.ProseMirror .author-marks .orcid { display: none; }\n.paper-pdf.ProseMirror .p-authors > span[data-rash-author][data-orcid]::before { content: \"iD\"; display: inline-flex; align-items: center; justify-content: center; width: 2em; height: 2em; margin-right: .5em; border-radius: 50%; background: #a6ce39; color: #fff; font: 700 .55em/1 Helvetica, Arial, sans-serif; letter-spacing: 0; vertical-align: .15em; }\n",
